// Manual adjacent ABI migration generated by `pina migrations make`.
// Source version: 0 (variable bytes)
// Destination version: 1 (variable bytes)
pub(crate) fn target_size(data: &[u8]) -> Option<usize> {
	5_usize.checked_add(usize::from(*data.get(2)?))
}

#[allow(clippy::unnecessary_wraps)]
pub(crate) fn working_size(data: &[u8], target_size: usize) -> Option<usize> {
	Some(data.len().max(target_size))
}

pub(crate) fn migrate(data: &mut [u8]) {
	let name_len = usize::from(data[2]);
	data.copy_within(3..3 + name_len, 5);
	data[3..5].fill(0);
}
